58	// 一次完整的 HTTP 请求（头部已解析、请求体已读满）。
59	struct HttpRequest {
60	  std::string method;
61	  std::string target;  // 原始 request-target（含 query）
62	  std::string path;    // 剥掉 query/fragment 的路径
63	  std::string query;   // 不含 '?'
64	  std::string body;
65	  std::string authorization;
66	};
67	
68	// 一次响应（状态行 + 内容类型 + 内容）。
69	struct HttpResponse {
70	  std::string status = "200 OK";
71	  std::string content_type = "application/json";
72	  std::string body;
73	};
74	
75	// 纯 JSON 错误体。
76	std::string JsonErrorBody(const std::string& error, const std::string& detail = "") {
77	  std::string out = "{" + JsonStringPair("error", error);
78	  if (!detail.empty()) {
79	    out += "," + JsonStringPair("detail", detail);
80	  }
81	  out += "}";
82	  return out;
83	}
84	
85	// 从 ad-hoc JSON 体里读一个整数；解析不了就返回默认值（绝不抛异常）。
86	long long SafeScanInt(const std::string& text, std::size_t from) {
87	  std::size_t i = from;
88	  while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
89	  bool negative = false;
90	  if (i < text.size() && (text[i] == '-' || text[i] == '+')) {
91	    negative = (text[i] == '-');
92	    ++i;
93	  }
94	  long long value = 0;
95	  bool any = false;
96	  while (i < text.size() && text[i] >= '0' && text[i] <= '9') {
97	    value = value * 10 + (text[i] - '0');
98	    if (value > 1000000000LL) {  // 地图尺寸/整数参数远小于此，超了按 0 处理
99	      return 0;
100	    }
101	    any = true;
102	    ++i;
103	  }
104	  if (!any) return 0;
105	  return negative ? -value : value;
106	}
107	
108	// 同理读一个浮点数：只接受 [-,+]digits[.digits][eE[+,-]digits] 的前缀。
109	double SafeScanDouble(const std::string& text, std::size_t from) {
110	  std::size_t i = from;
111	  while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
112	  const std::size_t begin = i;
113	  if (i < text.size() && (text[i] == '-' || text[i] == '+')) ++i;
114	  bool digits = false;
115	  while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
116	    ++i;
117	    digits = true;
118	  }
119	  if (i < text.size() && text[i] == '.') {
120	    ++i;
121	    while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
122	      ++i;
123	      digits = true;
124	    }
125	  }
126	  if (!digits) return 0.0;
127	  if (i < text.size() && (text[i] == 'e' || text[i] == 'E')) {
128	    std::size_t j = i + 1;
129	    if (j < text.size() && (text[j] == '+' || text[j] == '-')) ++j;
130	    bool exp_digits = false;
131	    while (j < text.size() && std::isdigit(static_cast<unsigned char>(text[j]))) {
132	      ++j;
133	      exp_digits = true;
134	    }
135	    if (exp_digits) i = j;
136	  }
137	  const std::string num = text.substr(begin, i - begin);
138	  try {
139	    return std::stod(num);
140	  } catch (...) {
141	    // num 已由上面的正则式扫描保证形状合法，这里只是防御
142	    return 0.0;
143	  }
144	}
145	
146	// 完整写出一段字节；对端提前关闭时返回 false（不抛、不崩）。
147	bool WriteAll(int fd, const std::string& data) {
148	  std::size_t sent = 0;
149	  while (sent < data.size()) {
150	    const ssize_t n = ::send(fd, data.data() + sent, data.size() - sent, MSG_NOSIGNAL);
151	    if (n > 0) {
152	      sent += static_cast<std::size_t>(n);
153	      continue;
154	    }
155	    if (n < 0 && errno == EINTR) continue;
156	    return false;  // EPIPE / EAGAIN（已超时）/ 其它
157	  }
158	  return true;
159	}
160	
161	// 错误响应后先把对端还在发送的数据读掉再关闭。
162	// 直接 close 一个仍有未读数据的连接会发 RST，客户端可能连 400/413 都收不到。
163	// 上限 2 MiB + 单次读超时，恶意客户端最多多占一个读超时。
164	void DrainForClose(int fd, std::size_t max_bytes = 2U * 1024U * 1024U) {
165	  char sink[4096];
166	  std::size_t drained = 0;
167	  while (drained < max_bytes) {
168	    const ssize_t n = ::read(fd, sink, sizeof(sink));
169	    if (n > 0) {
170	      drained += static_cast<std::size_t>(n);
171	      continue;
172	    }
173	    if (n < 0 && errno == EINTR) continue;
174	    return;
175	  }
176	}
