317	 private:
318	  // ---------------------------------------------------------------------------
319	  // 连接调度：主线程只 accept，工作线程负责读写与业务
320	  // ---------------------------------------------------------------------------
321	  void RunServer() {
322	    server_fd_ = socket(AF_INET, SOCK_STREAM, 0);
323	    if (server_fd_ < 0) {
324	      RCLCPP_ERROR(get_logger(), "Failed to create socket");
325	      return;
326	    }
327	
328	    int opt = 1;
329	    setsockopt(server_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
330	
331	    sockaddr_in address{};
332	    address.sin_family = AF_INET;
333	    address.sin_addr.s_addr = INADDR_ANY;
334	    address.sin_port = htons(static_cast<uint16_t>(port_));
335	
336	    if (bind(server_fd_, (struct sockaddr*)&address, sizeof(address)) < 0) {
337	      RCLCPP_ERROR(get_logger(), "Socket bind failed on port %d", port_);
338	      return;
339	    }
340	
341	    if (listen(server_fd_, 64) < 0) {
342	      RCLCPP_ERROR(get_logger(), "Socket listen failed");
343	      return;
344	    }
345	
346	    while (running_ && rclcpp::ok()) {
347	      sockaddr_in client_addr{};
348	      socklen_t client_len = sizeof(client_addr);
349	      const int client_fd = accept(server_fd_, (struct sockaddr*)&client_addr, &client_len);
350	      if (client_fd < 0) {
351	        if (!running_) break;
352	        if (errno == EINTR) continue;
353	        continue;
354	      }
355	      // 每个连接都必须有限等待：静默连接不能永久占住工作线程
356	      timeval tv{};
357	      tv.tv_sec = kSocketTimeoutSec;
358	      tv.tv_usec = 0;
359	      setsockopt(client_fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
360	      setsockopt(client_fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
361	
362	      bool queued = false;
363	      {
364	        std::lock_guard<std::mutex> lock(queue_mutex_);
365	        if (pending_.size() < max_pending_) {
366	          pending_.push_back(client_fd);
367	          queued = true;
368	        }
369	      }
370	      if (!queued) {
371	        // 过载保护：立刻回 503 并关闭，避免无界积压把内存吃光
372	        HttpResponse resp;
373	        resp.status = "503 Service Unavailable";
374	        resp.body = JsonErrorBody("gateway_overloaded", "too many pending connections");
375	        RecordRequestStatus(resp.status);
376	        WriteAll(client_fd, SerializeResponse(resp, false));
377	        close(client_fd);
378	        continue;
379	      }
380	      queue_cv_.notify_one();
381	    }
382	  }
383	
384	  void WorkerLoop() {
385	    while (true) {
386	      int client_fd = -1;
387	      {
388	        std::unique_lock<std::mutex> lock(queue_mutex_);
389	        queue_cv_.wait(lock, [this] { return stopping_ || !pending_.empty(); });
390	        if (stopping_ && pending_.empty()) {
391	          return;
392	        }
393	        client_fd = pending_.front();
394	        pending_.pop_front();
395	      }
396	      HandleClientSafely(client_fd);
397	      close(client_fd);
398	    }
399	  }
400	
401	  // 任何异常都必须收敛成 400：旧实现里一个 stoi 抛异常就把整个进程 terminate。
402	  void HandleClientSafely(int client_fd) {
403	    try {
404	      HandleClient(client_fd);
405	    } catch (const std::exception& e) {
406	      RCLCPP_WARN(get_logger(), "请求处理异常（已兜底为 400）: %s", e.what());
407	      HttpResponse resp;
408	      resp.status = "400 Bad Request";
409	      resp.body = JsonErrorBody("bad_request");
410	      RecordRequestStatus(resp.status);
411	      WriteAll(client_fd, SerializeResponse(resp, false));
412	    } catch (...) {
413	      RCLCPP_WARN(get_logger(), "请求处理未知异常（已兜底为 400）");
414	      HttpResponse resp;
415	      resp.status = "400 Bad Request";
416	      resp.body = JsonErrorBody("bad_request");
417	      RecordRequestStatus(resp.status);
418	      WriteAll(client_fd, SerializeResponse(resp, false));
419	    }
420	  }
421	
422	  // ---------------------------------------------------------------------------
423	  // 请求读取：头部上限、请求体上限、Content-Length 严格解析、分块传输拒绝
424	  // ---------------------------------------------------------------------------
425	  enum class ReadStatus { kOk, kClosed, kBadRequest, kTooLarge };
426	
427	  ReadStatus ReadRequest(int client_fd, HttpRequest* out) {
428	    std::string raw;
429	    raw.reserve(1024);
430	    char buffer[4096];
431	
432	    // 1) 读到头部结束标记
433	    std::size_t header_end = std::string::npos;
434	    while (true) {
435	      header_end = raw.find("\r\n\r\n");
436	      if (header_end != std::string::npos) {
437	        break;
438	      }
439	      if (raw.size() > kMaxHeaderBytes) {
440	        return ReadStatus::kBadRequest;
441	      }
442	      const ssize_t n = ::read(client_fd, buffer, sizeof(buffer));
443	      if (n == 0) {
444	        return ReadStatus::kClosed;
445	      }
446	      if (n < 0) {
447	        if (errno == EINTR) continue;
448	        return ReadStatus::kClosed;  // 超时(EAGAIN) 或对端重置
449	      }
450	      raw.append(buffer, static_cast<std::size_t>(n));
451	    }
452	    if (header_end > kMaxHeaderBytes) {
453	      return ReadStatus::kBadRequest;  // 头部过大
454	    }
455	    const std::string head = raw.substr(0, header_end);
456	
457	    // 2) 请求行
458	    std::istringstream first_line(head.substr(0, head.find("\r\n")));
459	    std::string version;
460	    first_line >> out->method >> out->target >> version;
461	    if (out->method.empty() || out->target.empty()) {
462	      return ReadStatus::kBadRequest;
463	    }
464	    out->path = RequestPathOnly(out->target);
465	    out->query = RequestQueryOnly(out->target);
466	    FindHeaderValue(head, "Authorization", &out->authorization);
467	
468	    // 3) 请求体长度：分块传输不支持（猜长度 = 读到连接耗尽，直接拒绝）
469	    if (HasChunkedTransferEncoding(head)) {
470	      return ReadStatus::kBadRequest;
471	    }
472	    std::size_t content_length = 0;
473	    std::string cl_value;
474	    if (FindHeaderValue(head, "Content-Length", &cl_value)) {
475	      switch (ParseContentLength(cl_value, &content_length)) {
476	        case ContentLengthStatus::kOk:
477	          break;
478	        case ContentLengthStatus::kMissing:
479	          content_length = 0;
480	          break;
481	        case ContentLengthStatus::kTooLarge:
482	          return ReadStatus::kTooLarge;
483	        case ContentLengthStatus::kInvalid:
484	          return ReadStatus::kBadRequest;
485	      }
486	    }
487	
488	    // 4) 读满请求体（总字节数同样受上限约束）
489	    const std::size_t body_begin = header_end + 4;
490	    std::size_t body_size = raw.size() - body_begin;
491	    if (body_size > content_length) {
492	      body_size = content_length;  // 多读的属于下一个请求（本网关一连接一请求，丢弃）
493	    }
494	    while (body_size < content_length) {
495	      const ssize_t n = ::read(client_fd, buffer, sizeof(buffer));
496	      if (n == 0) {
497	        return ReadStatus::kBadRequest;  // 声明了长度却提前断开
498	      }
499	      if (n < 0) {
500	        if (errno == EINTR) continue;
501	        return ReadStatus::kClosed;
502	      }
503	      body_size += static_cast<std::size_t>(n);
504	      raw.append(buffer, static_cast<std::size_t>(n));
505	      if (body_size > kMaxRequestBytes) {
506	        return ReadStatus::kTooLarge;
507	      }
508	    }
509	    out->body = raw.substr(body_begin, content_length);
510	    return ReadStatus::kOk;
511	  }
512	
513	  // ---------------------------------------------------------------------------
514	  // 请求分发
515	  // ---------------------------------------------------------------------------
516	  void HandleClient(int client_fd) {
517	    HttpRequest req;
518	    const ReadStatus status = ReadRequest(client_fd, &req);
519	    if (status == ReadStatus::kClosed) {
520	      return;  // 对端没发完整请求就断了：静默关闭
521	    }
522	    if (status == ReadStatus::kBadRequest) {
523	      HttpResponse resp;
524	      resp.status = "400 Bad Request";
525	      resp.body = JsonErrorBody("bad_request");
526	      RecordRequestStatus(resp.status);
527	      WriteAll(client_fd, SerializeResponse(resp, false));
528	      DrainForClose(client_fd, 64U * 1024U);
529	      return;
530	    }
531	    if (status == ReadStatus::kTooLarge) {
532	      HttpResponse resp;
533	      resp.status = "413 Payload Too Large";
534	      resp.body = JsonErrorBody("payload_too_large");
535	      RecordRequestStatus(resp.status);
536	      WriteAll(client_fd, SerializeResponse(resp, false));
537	      DrainForClose(client_fd);
538	      return;
539	    }
540	
541	    if (req.method == "OPTIONS") {
542	      HttpResponse resp;
543	      resp.status = "204 No Content";
544	      resp.body.clear();
545	      resp.content_type.clear();
546	      RecordRequestStatus(resp.status);
547	      WriteAll(client_fd, SerializeResponse(resp, true));
548	      return;
549	    }
550	
551	    // 鉴权中间件：auth_token 为空时 IsAuthorized 恒真（默认关闭）
552	    if (!IsAuthExemptPath(req.path) && !Authorize(req)) {
553	      HttpResponse resp;
554	      resp.status = "401 Unauthorized";
555	      resp.body = JsonErrorBody("unauthorized");
556	      std::string raw = "HTTP/1.1 401 Unauthorized\r\n";
557	      raw += "Content-Type: application/json\r\n";
558	      raw += "Content-Length: " + std::to_string(resp.body.size()) + "\r\n";
559	      raw += "WWW-Authenticate: Bearer\r\n";
560	      raw += ExtraHeaders();
561	      raw += "Connection: close\r\n\r\n";
562	      raw += resp.body;
563	      RecordRequestStatus(resp.status);
564	      WriteAll(client_fd, raw);
565	      return;
566	    }
567	
568	    const HttpResponse resp = Dispatch(req);
569	    RecordRequestStatus(resp.status);
570	    WriteAll(client_fd, SerializeResponse(resp, true));
571	  }
572	
573	  // 状态码按前三位归类（"200 OK" -> "200"），保证指标标签基数有限
574	  void RecordRequestStatus(const std::string& status) {
575	    const std::string code = status.substr(0, std::min<std::size_t>(3, status.size()));
576	    std::lock_guard<std::mutex> lock(data_mutex_);
577	    ++request_counts_[code];
578	  }
579	
580	  bool Authorize(const HttpRequest& req) const {
581	    // 急停可单独配口令；estop_token 为空时回退 auth_token
582	    if (req.path == "/metrics") {
583	      return IsAuthorized(req.authorization, metrics_token_);
584	    }
585	    if (req.path == "/api/operator/estop") {
586	      return IsAuthorized(req.authorization, estop_token_);
587	    }
588	    return IsAuthorized(req.authorization, auth_token_);
589	  }
590	
591	  HttpResponse Dispatch(const HttpRequest& req) {
592	    HttpResponse resp;
593	    const std::string& method = req.method;
594	    const std::string& path = req.path;
595	
596	    // 精确路由：旧实现用 find() 子串匹配，/api/v1/ordersXYZ 也会命中订单路由
597	    if (method == "GET" && PathMatchesAny(path, "/", "/index.html")) {
598	      resp.content_type = "text/html; charset=utf-8";
599	      resp.body = ReadStaticHtml();
600	      if (resp.body.empty()) {
601	        resp.status = "404 Not Found";
602	        resp.content_type = "text/html; charset=utf-8";
603	        resp.body = "<h1>404 Not Found: operator_console.html</h1>";
604	      }
605	      return resp;
606	    }
607	    if (method == "GET" && PathMatchesAny(path, "/api/operator/snapshot", "/api/v1/state")) {
608	      resp.body = FormatSnapshotJson();
609	      return resp;
610	    }
611	    if (method == "GET" && PathMatches(path, "/api/v1/vehicle_links")) {
612	      resp.body = FormatVehicleLinksJson();
613	      return resp;
614	    }
615	    if (method == "POST" && PathMatches(path, "/api/v1/force_clear_link")) {
616	      return HandleForceClear(req);
617	    }
618	    if (method == "POST" && PathMatches(path, "/api/v1/restore_link")) {
619	      return HandleRestore(req);
620	    }
621	    if (method == "GET" && PathMatches(path, "/metrics")) {
622	      resp.status = "200 OK";
623	      resp.content_type = "text/plain; version=0.0.4; charset=utf-8";
624	      resp.body = RenderMetrics();
625	      return resp;
626	    }
627	    if (method == "GET" && PathMatches(path, "/api/system/ready")) {
628	      return HandleReadiness();
629	    }
630	    if (method == "POST" && PathMatches(path, "/api/v1/orders")) {
631	      return HandleSubmitOrder(req);
632	    }
633	    if (method == "POST" && PathMatchesAny(path, "/api/v1/cancel", "/api/workflows/cancel")) {
634	      return HandleCancel(req);
635	    }
636	    if (method == "POST" && PathMatches(path, "/api/operator/estop")) {
637	      std_msgs::msg::Bool estop_msg;
638	      estop_msg.data = true;
639	      estop_pub_->publish(estop_msg);
640	      resp.body = "{\"status\":\"ok\",\"estop_engaged\":true}";
641	      return resp;
642	    }
643	    if (method == "POST" && PathMatches(path, "/api/v1/map/upload")) {
644	      return HandleMapUpload(req);
645	    }
646	
647	    resp.status = "404 Not Found";
648	    resp.body = JsonErrorBody("not_found");
649	    return resp;
650	  }
651	
652	  HttpResponse HandleForceClear(const HttpRequest& req) {
653	    HttpResponse resp;
654	    const std::string vehicle_id = JsonStringField(req.body, "vehicle_id");
655	    const std::string confirm_id = JsonStringField(req.body, "confirm_vehicle_id");
656	    const std::string operator_id = JsonStringField(req.body, "operator_id");
657	    const std::string reason = JsonStringField(req.body, "reason");
658	    if (vehicle_id.empty() || confirm_id.empty() || operator_id.empty() || reason.empty()) {
659	      resp.status = "400 Bad Request";
660	      resp.body = "{\"error\":\"missing_fields\",\"detail\":\"vehicle_id, confirm_vehicle_id, "
661	                  "operator_id, reason are all required\"}";
662	      return resp;
663	    }
664	    auto request = std::make_shared<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Request>();
665	    request->vehicle_id = vehicle_id;
666	    request->confirm_vehicle_id = confirm_id;
667	    request->operator_id = operator_id;
668	    request->reason = reason;
669	    if (!force_clear_cli_->wait_for_service(1s)) {
670	      resp.status = "503 Service Unavailable";
671	      resp.body = JsonErrorBody("service_unavailable");
672	      return resp;
673	    }
674	    auto fut = force_clear_cli_->async_send_request(request);
675	    if (fut.wait_for(2s) != std::future_status::ready) {
676	      resp.status = "504 Gateway Timeout";
677	      resp.body = JsonErrorBody("timeout");
678	      return resp;
679	    }
680	    auto res = fut.get();
681	    std::string body = "{\"status\":\"" + std::string(res->success ? "ok" : "rejected") + "\",";
682	    body += JsonStringPair("message", res->message) + ",\"quarantined\":";
683	    body += (res->quarantined ? "true" : "false");
684	    body += ",\"released_resources\":[";
685	    for (std::size_t i = 0; i < res->released_resources.size(); ++i) {
686	      if (i) body += ",";
687	      body += "\"" + JsonEscape(res->released_resources[i]) + "\"";
688	    }
689	    body += "]}";
690	    resp.body = body;
691	    if (!res->success) {
692	      resp.status = "409 Conflict";
693	    }
694	    return resp;
695	  }
