762	  HttpResponse HandleSubmitOrder(const HttpRequest& req) {
763	    HttpResponse resp;
764	    if (req.query.empty()) {
765	      resp.status = "400 Bad Request";
766	      resp.body = JsonErrorBody("missing_query_parameters");
767	      return resp;
768	    }
769	    const std::string mid = GetQueryParam(req.query, "id");
770	    const std::string from = GetQueryParam(req.query, "from");
771	    const std::string to = GetQueryParam(req.query, "to");
772	    const std::string vehicle = GetQueryParam(req.query, "vehicle");
773	    const std::string ikey = GetQueryParam(req.query, "idempotency_key");
774	    // 批次 6.4：补齐上游契约字段透传（此前网关只传 id/from/to/prio/vehicle，
775	    // 业务订单号、截止期、任务类型在网关这一层被静默丢弃）。
776	    const std::string order_id = GetQueryParam(req.query, "order_id");
777	    const std::string mission_type = GetQueryParam(req.query, "type");
778	    const std::string deadline_text = GetQueryParam(req.query, "deadline_unix_ms");
779	    const std::string expected_text = GetQueryParam(req.query, "expected_seconds");
780	
781	    std::int32_t prio = 5;
782	    const std::string prio_text = GetQueryParam(req.query, "prio", "5");
783	    switch (ParseInt32Strict(prio_text, &prio)) {
784	      case IntParseStatus::kOk:
785	        break;
786	      case IntParseStatus::kOutOfRange:
787	        resp.status = "400 Bad Request";
788	        resp.body = JsonErrorBody("invalid_priority", "prio out of range");
789	        return resp;
790	      case IntParseStatus::kInvalid:
791	        // 旧实现 std::stoi("notanumber") 直接 terminate 整个网关
792	        resp.status = "400 Bad Request";
793	        resp.body = JsonErrorBody("invalid_priority", "prio must be an integer");
794	        return resp;
795	    }
796	
797	    // 可选数值字段：给了就必须是合法整数（绝不静默当 0——那会让任务"没有截止期"
798	    // 而调用方以为设上了）。截止期额外要求为正数。
799	    std::int64_t deadline_unix_ms = 0;
800	    if (!deadline_text.empty()) {
801	      std::int32_t parsed = 0;
802	      if (ParseInt32Strict(deadline_text, &parsed) != IntParseStatus::kOk || parsed <= 0) {
803	        resp.status = "400 Bad Request";
804	        resp.body = JsonErrorBody("invalid_deadline", "deadline_unix_ms must be a positive integer");
805	        return resp;
806	      }
807	      deadline_unix_ms = parsed;
808	    }
809	    std::int32_t expected_seconds = 0;
810	    if (!expected_text.empty()) {
811	      if (ParseInt32Strict(expected_text, &expected_seconds) != IntParseStatus::kOk ||
812	          expected_seconds < 0) {
813	        resp.status = "400 Bad Request";
814	        resp.body = JsonErrorBody("invalid_expected_seconds",
815	                                  "expected_seconds must be a non-negative integer");
816	        return resp;
817	      }
818	    }
819	
820	    // 幂等：先占位，只有后端**确认受理**才 Commit；失败/超时 Abort 允许重试
821	    bool reserved = false;
822	    if (!ikey.empty()) {
823	      const auto result = ReserveIdempotency(ikey);
824	      if (result == IdempotencyStore::ReserveResult::kDuplicate) {
825	        resp.body = "{\"status\":\"ignored\",\"reason\":\"idempotent_duplicate\"}";
826	        return resp;
827	      }
828	      if (result == IdempotencyStore::ReserveResult::kInvalidKey) {
829	        resp.status = "400 Bad Request";
830	        resp.body = JsonErrorBody("invalid_idempotency_key");
831	        return resp;
832	      }
833	      if (result == IdempotencyStore::ReserveResult::kFull) {
834	        resp.status = "503 Service Unavailable";
835	        resp.body = JsonErrorBody("idempotency_store_full");
836	        return resp;
837	      }
838	      reserved = true;
839	    }
840	
841	    auto request = std::make_shared<amr_dispatcher_interfaces::srv::SubmitOrder::Request>();
842	    request->mission_id = mid;
843	    request->order_id = order_id;
844	    request->mission_type = mission_type;
845	    request->pickup_station = from;
846	    request->dropoff_station = to;
847	    request->priority = prio;
848	    request->deadline_unix_ms = deadline_unix_ms;
849	    request->expected_seconds = expected_seconds;
850	    request->assigned_vehicle_id = vehicle;
851	
852	    if (!submit_cli_->wait_for_service(1s)) {
853	      if (reserved) AbortIdempotency(ikey);
854	      resp.status = "503 Service Unavailable";
855	      resp.body = JsonErrorBody("service_unavailable");
856	      return resp;
857	    }
858	    auto fut = submit_cli_->async_send_request(request);
859	    if (fut.wait_for(2s) != std::future_status::ready) {
860	      if (reserved) AbortIdempotency(ikey);
861	      resp.status = "504 Gateway Timeout";
862	      resp.body = JsonErrorBody("timeout");
863	      return resp;
864	    }
865	    auto res = fut.get();
866	    // 后端给出了明确答复（受理或业务拒绝）就算消费掉该 key；只有传输失败才回滚
867	    if (reserved) CommitIdempotency(ikey);
868	    resp.body = "{\"status\":\"ok\",\"accepted\":" + std::string(res->accepted ? "true" : "false") +
869	                "," + JsonStringPair("mission_id", res->mission_id) + "}";
870	    return resp;
871	  }
