1194	  // 极简 JSON 字符串字段提取（请求体由本项目自己的控制台产生，格式可控）：
1195	  // 形如 "key": "value" -> value；缺失或非字符串返回空串。
1196	  static std::string JsonStringField(const std::string& body, const std::string& key) {
1197	    const std::string target = "\"" + key + "\"";
1198	    auto pos = body.find(target);
1199	    if (pos == std::string::npos) return "";
1200	    pos = body.find(':', pos);
1201	    if (pos == std::string::npos) return "";
1202	    ++pos;
1203	    while (pos < body.size() && std::isspace(static_cast<unsigned char>(body[pos]))) ++pos;
1204	    if (pos >= body.size() || body[pos] != '"') return "";
1205	    ++pos;
1206	    std::string value;
1207	    while (pos < body.size() && body[pos] != '"') {
1208	      if (body[pos] == '\\' && pos + 1 < body.size()) {
1209	        ++pos;
1210	        switch (body[pos]) {
1211	          case 'n': value.push_back('\n'); break;
1212	          case 't': value.push_back('\t'); break;
1213	          case 'r': value.push_back('\r'); break;
1214	          default: value.push_back(body[pos]); break;
1215	        }
1216	        ++pos;
1217	        continue;
1218	      }
1219	      value.push_back(body[pos]);
1220	      ++pos;
1221	    }
1222	    return value;
1223	  }
