1225	  // 极简 JSON 布尔字段提取：true / false。
1226	  static bool JsonBoolField(const std::string& body, const std::string& key) {
1227	    const std::string target = "\"" + key + "\"";
1228	    auto pos = body.find(target);
1229	    if (pos == std::string::npos) return false;
1230	    pos = body.find(':', pos);
1231	    if (pos == std::string::npos) return false;
1232	    ++pos;
1233	    while (pos < body.size() && std::isspace(static_cast<unsigned char>(body[pos]))) ++pos;
1234	    return body.compare(pos, 4, "true") == 0;
1235	  }
