1446	  // 原子落盘：tmp + rename。写失败只告警——去重是尽力而为，不能因此拒绝已经
1447	  // 被后端受理的订单（订单已经进队列了，返回错误反而误导调用方）。
1448	  void PersistIdempotency(const std::string& text) {
1449	    const std::filesystem::path final_path(idempotency_store_file_);
1450	    const std::filesystem::path tmp_path(final_path.string() + ".tmp");
1451	    std::error_code ec;
1452	    if (final_path.has_parent_path()) {
1453	      std::filesystem::create_directories(final_path.parent_path(), ec);
1454	    }
1455	    {
1456	      std::ofstream out(tmp_path, std::ios::trunc);
1457	      if (!out) {
1458	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1459	                             "Cannot open idempotency store temp file %s", tmp_path.c_str());
1460	        return;
1461	      }
1462	      out << text;
1463	      out.flush();
1464	      if (!out) {
1465	        out.close();
1466	        std::filesystem::remove(tmp_path, ec);
1467	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1468	                             "Failed writing idempotency store %s", tmp_path.c_str());
1469	        return;
1470	      }
1471	    }
1472	    std::filesystem::rename(tmp_path, final_path, ec);
1473	    if (ec) {
1474	      std::filesystem::remove(tmp_path, ec);
1475	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1476	                           "Atomic rename of idempotency store failed: %s", ec.message().c_str());
1477	    }
1478	  }
