40	DispatcherNode::DispatcherNode(const rclcpp::NodeOptions& options)
41	    : rclcpp_lifecycle::LifecycleNode("dispatcher_node", options) {
42	  declare_parameter("queue_capacity", 128);
43	  declare_parameter("comparator", "priority_fifo");
44	  declare_parameter("schedule_rate_hz", 10.0);
45	  declare_parameter("deadlock_check_rate_hz", 1.0);
46	  declare_parameter("max_active_missions", 4);
47	  declare_parameter("stations_file", "config/stations.yaml");
48	  declare_parameter("path_step_size_m", 0.1);
49	  declare_parameter("recovery_dock_station", "station_charge_1");
50	  declare_parameter("navigation_backend", "plan");
51	  // 路径规划器类型（skeleton|mock）与地图版本门禁期望哈希（空 = 关闭门禁）
52	  declare_parameter("planner_type", "skeleton");
53	  declare_parameter("expected_map_hash", "");
54	  // Task 5：受管 VDA 5050 小车清单（逗号分隔 vehicle_id；空 = 关闭逐段解锁/断链守卫）
55	  // 与 state 陈旧告警阈值（秒，在线但超时未上报 -> 仅告警不释放）
56	  declare_parameter("vda5050_vehicles", "");
57	  declare_parameter("vda5050_state_stale_sec", 5.0);
58	  // P0.6 / A4：本调度器管理的 local_sim 车辆清单（逗号分隔 vehicle_id；空 = 单车兼容模式）
59	  declare_parameter("vehicle_ids", "");
60	  // P0.6 / A6：车辆目录（静态）+ 选车参数
61	  declare_parameter("fleet_catalog_file", "");
62	  declare_parameter("required_capability", "transport");
63	  declare_parameter("min_battery_percent", 0.0);
64	  // 自动选车的打分策略：nearest（默认，改动前行为）| battery_preferred（低电量软降权）
65	  declare_parameter("vehicle_selection_strategy", "nearest");
66	  declare_parameter("vehicle_state_max_age_ms", 5000);
67	  // A6：选车扫描深度（队首阻塞规避）——一次 tick 最多考察前 N 个排队任务
68	  declare_parameter("assignment_scan_depth", 8);
69	  // B3：交通协调模式——static（静态排他锁，现网行为）| time_space（时空窗预约）
70	  declare_parameter("traffic_mode", "static");
71	  // 时空窗运动参数
72	  declare_parameter("time_space_cruise_speed_mps", 1.0);
73	  declare_parameter("time_space_accel_overhead_sec", 1.0);
74	  declare_parameter("time_space_turn_overhead_sec", 0.5);
75	  declare_parameter("time_space_safety_margin_m", 0.2);
76	  declare_parameter("time_space_min_headway_sec", 2.0);
77	  // 批次 2：状态持久化与审计落盘（全部默认关闭 = 现网行为不变）
78	  declare_parameter("state_snapshot_file", "");
79	  declare_parameter("state_snapshot_debounce_sec", 2.0);
80	  declare_parameter("audit_log_file", "");
81	  // Phase 8: 工业物理设施目录文件路径
82	  declare_parameter("facility_catalog_file", "");
83	  // 批次 6.2：低电量自动插充电单（默认关闭 = 现网行为不变）
84	  declare_parameter("auto_charging_enabled", false);
85	  declare_parameter("auto_charging_station", "");
86	  declare_parameter("auto_charging_opportunity_threshold_percent", 30.0);
87	  declare_parameter("auto_charging_critical_threshold_percent", 15.0);
88	  declare_parameter("auto_charging_opportunity_priority", 0);
89	  declare_parameter("auto_charging_critical_priority", 5);
90	  recovery_dock_station_ = get_parameter("recovery_dock_station").as_string();
91	  planner_type_ = get_parameter("planner_type").as_string();
92	  expected_map_hash_ = get_parameter("expected_map_hash").as_string();
93	}
