97	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
98	  const std::size_t cap = get_parameter("queue_capacity").as_int();
99	  const std::string comp_name = get_parameter("comparator").as_string();
100	
101	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
102	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
103	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
104	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
105	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
106	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
107	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
108	          10s, 30s});
109	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
110	
111	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
112	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
113	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
114	  const std::string stations_file = get_parameter("stations_file").as_string();
115	  catalog_reloader_ =
116	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
117	  if (catalog_reloader_->loaded()) {
118	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
119	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
120	  } else {
121	    RCLCPP_WARN(get_logger(),
122	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
123	                stations_file.c_str());
124	  }
125	  // 依 planner_type 选规划器：skeleton -> 混合图折线循迹，mock -> 直线基线。
126	  // catalog_reloader_ 已就位（即使初始加载失败也持有空目录，热重载后由 reload_timer_ 同步）。
127	  RebuildPlanner();
128	
129	  // ---- 批次 2：调度状态恢复（state_snapshot_file 为空 = 关闭）----
130	  state_snapshot_file_ = get_parameter("state_snapshot_file").as_string();
131	  state_snapshot_debounce_sec_ = get_parameter("state_snapshot_debounce_sec").as_double();
132	  audit_log_file_ = get_parameter("audit_log_file").as_string();
133	  if (!state_snapshot_file_.empty()) {
134	    std::string reason;
135	    const auto restored = amr_dispatcher_core::dispatcher::LoadDispatchState(
136	        state_snapshot_file_, &reason);
137	    if (!restored.has_value()) {
138	      if (reason == "not_found") {
139	        RCLCPP_INFO(get_logger(), "No dispatch state snapshot at %s (fresh start)",
140	                    state_snapshot_file_.c_str());
141	      } else {
142	        // 坏快照绝不"尽力而为"：拒绝恢复并保留现场，人工判断后再清理
143	        RCLCPP_ERROR(get_logger(),
144	                     "Refusing to restore dispatch state from %s: %s (starting fresh; "
145	                     "the file is left untouched for inspection)",
146	                     state_snapshot_file_.c_str(), reason.c_str());
147	      }
148	    } else {
149	      // 地图版本门禁：拿旧拓扑的队列去派发 = 派到不存在的站点
150	      const std::string current_map_hash =
151	          catalog_reloader_ ? catalog_reloader_->catalog().map_hash : std::string();
152	      if (!restored->map_hash.empty() && !current_map_hash.empty() &&
153	          restored->map_hash != current_map_hash) {
154	        RCLCPP_ERROR(get_logger(),
155	                     "Refusing to restore dispatch state: snapshot map_hash=%s does not match "
156	                     "current map_hash=%s (topology changed); starting with an empty queue",
157	                     restored->map_hash.c_str(), current_map_hash.c_str());
158	        AppendAudit("restore_state_rejected", "", "", "system",
159	                    "map_hash mismatch: snapshot=" + restored->map_hash +
160	                        " current=" + current_map_hash);
161	      } else {
162	        std::vector<amr_dispatcher_core::dispatcher::Mission> queued = restored->queued_missions;
163	        // 暂停订单下的任务先移出队列：它们在暂停期间本就不可派发，
164	        // 先入队再标暂停会被容量上限挤掉（等于丢单），所以恢复完暂停标记再补回。
165	        std::vector<amr_dispatcher_core::dispatcher::Mission> paused_backlog;
166	        std::unordered_set<std::string> paused_orders(restored->paused_order_ids.begin(),
167	                                                      restored->paused_order_ids.end());
168	        for (const auto& m : queued) {
169	          if (!m.order_id.empty() && paused_orders.count(m.order_id) > 0) {
170	            paused_backlog.push_back(m);  // 暂停期间本就不可派发：稍后补回
171	          }
172	        }
173	        queued.erase(std::remove_if(queued.begin(), queued.end(),
174	                                    [&paused_orders](const auto& m) {
175	                                      return !m.order_id.empty() &&
176	                                             paused_orders.count(m.order_id) > 0;
177	                                    }),
178	                     queued.end());
179	        // 重启时仍在执行的任务：新进程没有任何车辆在跑它们，重新入队而不是假装在途
180	        for (const auto& m : restored->active_missions) {
181	          amr_dispatcher_core::dispatcher::Mission requeued = m;
182	          requeued.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
183	          requeued.result = amr_dispatcher_core::dispatcher::MissionResult::kNone;
184	          requeued.reservation_id.clear();  // 旧锁属于已死亡的进程
185	          if (!requeued.order_id.empty() && paused_orders.count(requeued.order_id) > 0) {
186	            paused_backlog.push_back(std::move(requeued));
187	          } else {
188	            queued.push_back(std::move(requeued));
189	          }
190	        }
191	        std::size_t restored_count = queue_->Restore(queued, restored->paused_order_ids);
192	        if (!paused_backlog.empty()) {
193	          // 暂停标记已在 Restore 里生效，现在把它们补回队列（不受"可派"语义影响）
194	          restored_count += queue_->RestoreAppend(paused_backlog);
195	        }
196	        next_sequence_ = restored->next_sequence;
197	        // 隔离态必须等 SetupVda5050Links 之后再灌：它会先 clear() 旧链路态，
198	        // 此处直接写入会被随后的 clear 抹掉。
199	        restored_quarantined_ = restored->quarantined_vehicle_ids;
200	        RCLCPP_INFO(get_logger(),
201	                    "Restored dispatch state from %s: %zu queued (%zu re-queued from active), "
202	                    "%zu paused order(s), %zu quarantined vehicle(s), next_sequence=%llu",
203	                    state_snapshot_file_.c_str(), restored_count,
204	                    restored->active_missions.size(), restored->paused_order_ids.size(),
