646	  list_reservations_srv_.reset();
647	  reserve_facility_srv_.reset();
648	  snapshot_srv_.reset();
649	  validate_site_srv_.reset();
650	  // B2：clean up 前先逐个收口在途 ExecuteMission goal——
651	  // 不复位的 handle 在 server 销毁后会让 action 客户端永久悬挂；
652	  // 同时释放 HandleGoal 阶段预占的 required_resources 锁。
653	  // rclcpp_action 状态机约束：canceled() 仅 CANCELING、abort() 仅 EXECUTING，
654	  // 其余状态（ACCEPTED 未执行）先 execute() 再 abort()，与 FinishExecuteGoal 同构。
655	  for (auto& [mission_id, handle] : execute_goal_handles_) {
656	    if (!handle) {
657	      continue;
658	    }
659	    if (reservation_table_) {
660	      reservation_table_->Release(mission_id);
661	    }
662	    auto result = std::make_shared<ExecuteMission::Result>();
663	    result->success = false;
664	    result->error_code = 1;
665	    result->message = "dispatcher cleaning up";
666	    try {
667	      if (handle->is_canceling()) {
668	        handle->canceled(result);
669	      } else if (handle->is_executing()) {
670	        handle->abort(result);
671	      } else {
672	        handle->execute();
673	        handle->abort(result);
674	      }
675	    } catch (const std::exception& ex) {
676	      RCLCPP_ERROR(get_logger(), "on_cleanup: finish goal %s failed: %s",
677	                   mission_id.c_str(), ex.what());
678	    }
679	  }
680	  execute_action_server_.reset();
681	  nav_client_.reset();
682	  execute_goal_handles_.clear();
683	  mission_dispatch_start_.clear();
684	  mission_dispatch_time_.clear();
685	  pending_wait_.clear();
686	  mission_reserved_at_.clear();
687	  pending_nav_mission_id_.clear();
688	  pending_nav_goal_handle_.reset();
689	  state_pub_.reset();
690	  event_pub_.reset();
691	  plan_pub_.reset();
692	  topology_pub_.reset();
693	  vda5050_order_pubs_.clear();   // Task 6：随生命周期收口，重 configure 时重建
694	  vda5050_vehicle_ids_.clear();
695	  vda5050_link_subs_.clear();    // 终审 M4：与 SetupVda5050Links 开头清旧对齐，防残留链
696	  vda5050_link_states_.clear();
697	  vda5050_next_order_update_id_.clear();
698	  vda5050_mission_vehicle_.clear();  // Task 7：mission->车辆绑定随生命周期收口
699	  // 隔离态随生命周期收口（隔离位存在链路态表里，上方的 clear 已经清掉）
700	  // P0.6：per-vehicle 资源随生命周期收口，重 configure 时重建
701	  vehicle_plan_pubs_.clear();
702	  vehicle_odom_subs_.clear();
703	  vehicle_tracking_error_subs_.clear();
704	  vehicle_poses_.clear();
705	  vehicle_ids_.clear();
706	  last_deadlock_findings_.clear();
707	  tracking_error_sub_.reset();
708	  odom_sub_.reset();
709	  queue_.reset();
710	  reservation_table_.reset();
711	  // 批次 2：持久化通道随生命周期收口（快照文件本身保留，供下次启动恢复）
712	  state_snapshot_dirty_ = false;
713	  last_state_snapshot_error_.clear();
714	  event_log_.reset();
715	  deadlock_detector_.reset();
716	  recovery_policy_.reset();
717	  planner_.reset();
718	  catalog_reloader_.reset();
719	  reload_timer_.reset();
720	  // 批次 2：持久化开关随生命周期收口（配置在下一次 configure 重新读取）。
721	  // 手动生命周期切换（deactivate -> cleanup -> configure）不应把上一次的
722	  // 队列当成"重启恢复"再灌一遍。
723	  state_snapshot_file_.clear();
724	  audit_log_file_.clear();
725	  restored_quarantined_.clear();
726	  queue_start_requested_ = false;
727	  vehicle_current_mission_.clear();
728	  mission_tracking_vehicle_.clear();
729	  vehicle_states_.clear();
730	  auto_assignment_paused_ = false;
731	  time_space_occupancy_ = amr_dispatcher_core::workflow::TimeSpaceOccupancy{};
732	  time_space_windows_.clear();
733	  active_missions_.clear();
734	  return CallbackReturn::SUCCESS;
735	}
