    // cycle_path 为任务/资源交替闭合序列：奇数位才是资源 id（任务 id 不得混入）
    for (std::size_t i = 1; i < f.cycle_path.size(); i += 2) {
      resp->conflict_resource_ids.push_back(f.cycle_path[i]);
    }
    resp->descriptions.push_back(f.description);
  }
