1	// 静态 Bearer Token 鉴权（纯函数，无 IO）。
2	//
3	// 默认关闭：expected_token 为空时 IsAuthorized 恒真——现网与所有 e2e 的行为
4	// 逐字不变。配置了 token 才要求 `Authorization: Bearer <token>`。
5	//
6	// 比较用常量时间，避免按字符提前返回泄露 token 前缀。
7	#pragma once
8	
9	#include <cstddef>
10	#include <string>
11	
12	#include "amr_dispatcher_tools/http_limits.hpp"
13	
