731	    const stationTypeSelect = document.getElementById('stationTypeSelect');
732	    const anchorListEl = document.getElementById('anchorList');
733	    const anchorCountEl = document.getElementById('anchorCount');
734	    const clearAnchorsBtn = document.getElementById('clearAnchorsBtn');
735	    const uploadMapBtn = document.getElementById('uploadMapBtn');
736	
737	    let currentMapImage = null;
738	    let mapWidth = 0, mapHeight = 0;
739	    let gridData = [];
740	    let anchors = [];
741	
742	    // 文件读取与 Canvas 渲染
743	    mapFileInput.addEventListener('change', (e) => {
744	      const file = e.target.files[0];
745	      if (!file) return;
746	
747	      const reader = new FileReader();
748	      const isPgm = file.name.toLowerCase().endsWith('.pgm');
749	
750	      if (isPgm) {
751	        reader.readAsArrayBuffer(file);
752	        reader.onload = () => {
753	          parseAndRenderPgm(new Uint8Array(reader.result));
754	        };
755	      } else {
756	        reader.readAsDataURL(file);
757	        reader.onload = () => {
758	          const img = new Image();
759	          img.onload = () => {
760	            renderImageToCanvas(img);
761	          };
762	          img.src = reader.result;
763	        };
764	      }
765	    });
766	
767	    function parseAndRenderPgm(bytes) {
768	      // 解析 P5 二进制 PGM
769	      let offset = 0;
770	      function readToken() {
771	        while (offset < bytes.length && (bytes[offset] === 32 || bytes[offset] === 10 || bytes[offset] === 13 || bytes[offset] === 9)) offset++;
772	        if (offset >= bytes.length) return "";
773	        if (bytes[offset] === 35) { // comment #
774	          while (offset < bytes.length && bytes[offset] !== 10 && bytes[offset] !== 13) offset++;
775	          return readToken();
776	        }
777	        let start = offset;
778	        while (offset < bytes.length && bytes[offset] !== 32 && bytes[offset] !== 10 && bytes[offset] !== 13 && bytes[offset] !== 9) offset++;
779	        return String.fromCharCode.apply(null, bytes.subarray(start, offset));
780	      }
781	
782	      const magic = readToken();
783	      if (magic !== 'P5') {
784	        alert("目前仅支持二进制 PGM (P5) 格式！");
785	        return;
786	      }
787	      mapWidth = parseInt(readToken());
788	      mapHeight = parseInt(readToken());
789	      const maxVal = parseInt(readToken());
790	      offset++; // skip trailing newline
791	
792	      mapCanvas.width = mapWidth;
793	      mapCanvas.height = mapHeight;
794	      const ctx = mapCanvas.getContext('2d');
795	      const imgData = ctx.createImageData(mapWidth, mapHeight);
796	      gridData = new Array(mapWidth * mapHeight);
797	
798	      // PGM 坐标系：左上为 (0,0)，ROS 栅格通常以左下为 (0,0)
799	      for (let r = 0; r < mapHeight; r++) {
800	        for (let c = 0; c < mapWidth; c++) {
801	          const val = bytes[offset + r * mapWidth + c];
802	          const pxIdx = (r * mapWidth + c) * 4;
803	          imgData.data[pxIdx] = val;
804	          imgData.data[pxIdx + 1] = val;
805	          imgData.data[pxIdx + 2] = val;
806	          imgData.data[pxIdx + 3] = 255;
807	
808	          // 转换为 ROS 栅格占用概率 (-1, 0, 100)
809	          // ROS 占据栅格行号从下到上：ros_row = (mapHeight - 1 - r)
810	          const rosRow = mapHeight - 1 - r;
811	          const rosIdx = rosRow * mapWidth + c;
812	          if (val === 254 || val > 240) gridData[rosIdx] = 0; // free
813	          else if (val === 0 || val < 50) gridData[rosIdx] = 100; // occupied
814	          else gridData[rosIdx] = -1; // unknown
815	        }
816	      }
817	      ctx.putImageData(imgData, 0, 0);
818	      currentMapImage = imgData;
819	      canvasOverlayText.style.display = 'none';
820	      redrawCanvas();
821	    }
822	
823	    function renderImageToCanvas(img) {
824	      mapWidth = img.width;
825	      mapHeight = img.height;
826	      mapCanvas.width = mapWidth;
827	      mapCanvas.height = mapHeight;
828	      const ctx = mapCanvas.getContext('2d');
829	      ctx.drawImage(img, 0, 0);
830	      const imgData = ctx.getImageData(0, 0, mapWidth, mapHeight);
831	      currentMapImage = imgData;
832	      gridData = new Array(mapWidth * mapHeight);
833	
834	      for (let r = 0; r < mapHeight; r++) {
835	        for (let c = 0; c < mapWidth; c++) {
836	          const pxIdx = (r * mapWidth + c) * 4;
837	          const gray = (imgData.data[pxIdx] + imgData.data[pxIdx+1] + imgData.data[pxIdx+2]) / 3;
838	          const rosRow = mapHeight - 1 - r;
839	          const rosIdx = rosRow * mapWidth + c;
840	          if (gray > 200) gridData[rosIdx] = 0;
841	          else if (gray < 80) gridData[rosIdx] = 100;
842	          else gridData[rosIdx] = -1;
843	        }
844	      }
845	      canvasOverlayText.style.display = 'none';
846	      redrawCanvas();
847	    }
848	
849	    // 鼠标点击标注站点
850	    mapCanvas.addEventListener('click', (e) => {
851	      if (!currentMapImage) return;
852	      const rect = mapCanvas.getBoundingClientRect();
853	      const scaleX = mapCanvas.width / rect.width;
854	      const scaleY = mapCanvas.height / rect.height;
855	
856	      const clickCol = Math.round((e.clientX - rect.left) * scaleX);
857	      const clickRow = Math.round((e.clientY - rect.top) * scaleY);
858	
859	      // 计算对应的米制坐标：ROS 行号为 mapHeight - 1 - clickRow
860	      const res = parseFloat(document.getElementById('mapResInput').value) || 0.05;
861	      const ox = parseFloat(document.getElementById('mapOriginXInput').value) || 0.0;
862	      const oy = parseFloat(document.getElementById('mapOriginYInput').value) || 0.0;
863	
864	      const rosRow = mapHeight - 1 - clickRow;
865	      const worldX = parseFloat((ox + (clickCol + 0.5) * res).toFixed(3));
866	      const worldY = parseFloat((oy + (rosRow + 0.5) * res).toFixed(3));
867	
868	      const type = stationTypeSelect.value;
869	      const autoId = `station_${type}_${anchors.length + 1}`;
870	
871	      anchors.push({
872	        id: autoId,
873	        type: type,
874	        x: worldX,
875	        y: worldY,
876	        yaw: 0.0,
877	        pixelCol: clickCol,
878	        pixelRow: clickRow
879	      });
880	
881	      renderAnchorList();
882	      redrawCanvas();
883	    });
884	
885	    clearAnchorsBtn.addEventListener('click', () => {
886	      anchors = [];
887	      renderAnchorList();
888	      redrawCanvas();
889	    });
890	
891	    function renderAnchorList() {
892	      anchorCountEl.textContent = anchors.length;
893	      anchorListEl.innerHTML = anchors.map((a, i) => `
894	        <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 4px;border-bottom:1px solid #edf2f7;">
895	          <span><b>${a.id}</b> (${a.type}) [${a.x}, ${a.y}]</span>
896	          <span style="color:var(--danger);cursor:pointer;font-weight:bold;" onclick="deleteAnchor(${i})">×</span>
897	        </div>
898	      `).join('') || '<div style="color:#94a3b8;padding:6px;">暂无标注，请点击右侧地图添加</div>';
899	    }
900	
901	    window.deleteAnchor = function(idx) {
902	      anchors.splice(idx, 1);
903	      renderAnchorList();
904	      redrawCanvas();
905	    };
906	
907	    function redrawCanvas() {
908	      if (!currentMapImage) return;
909	      const ctx = mapCanvas.getContext('2d');
910	      ctx.putImageData(currentMapImage, 0, 0);
911	
912	      // 绘制所有站点
913	      anchors.forEach((a) => {
914	        ctx.beginPath();
915	        ctx.arc(a.pixelCol, a.pixelRow, 7, 0, Math.PI * 2);
916	        if (a.type === 'pickup') ctx.fillStyle = '#22c55e';
917	        else if (a.type === 'dropoff') ctx.fillStyle = '#f97316';
918	        else if (a.type === 'charge') ctx.fillStyle = '#eab308';
919	        else ctx.fillStyle = '#3b82f6';
920	        ctx.fill();
921	        ctx.lineWidth = 2;
922	        ctx.strokeStyle = '#ffffff';
923	        ctx.stroke();
924	
925	        ctx.font = 'bold 11px sans-serif';
926	        ctx.fillStyle = '#ffffff';
927	        ctx.strokeStyle = '#000000';
928	        ctx.lineWidth = 3;
929	        ctx.strokeText(a.id, a.pixelCol + 9, a.pixelRow + 4);
930	        ctx.fillText(a.id, a.pixelCol + 9, a.pixelRow + 4);
931	      });
932	    }
933	
934	    // 一键上传并热更新
935	    uploadMapBtn.addEventListener('click', async () => {
936	      if (!currentMapImage || gridData.length === 0) {
937	        alert("请先选择或拖拽地图文件！");
938	        return;
939	      }
940	      if (anchors.length === 0) {
941	        alert("请在地图上至少点击标注一个站点！");
942	        return;
943	      }
944	
945	      const res = parseFloat(document.getElementById('mapResInput').value) || 0.05;
946	      const ox = parseFloat(document.getElementById('mapOriginXInput').value) || 0.0;
947	      const oy = parseFloat(document.getElementById('mapOriginYInput').value) || 0.0;
948	      const baseUrl = baseUrlInput.value.replace(/\/$/, '');
949	
950	      const payload = {
951	        width: mapWidth,
952	        height: mapHeight,
953	        resolution: res,
954	        origin_x: ox,
955	        origin_y: oy,
956	        grid_data: gridData,
957	        anchors: anchors.map(a => ({
958	          id: a.id,
959	          type: a.type,
960	          x: a.x,
961	          y: a.y,
962	          yaw: a.yaw
963	        }))
964	      };
965	
966	      try {
967	        setStatus("🚀 正在生成骨架路网并原子重载调度拓扑...", true);
968	        uploadMapBtn.disabled = true;
969	        uploadMapBtn.textContent = "⏳ 正在提取拓扑...";
970	
971	        const resp = await fetch(`${baseUrl}/api/v1/map/upload`, {
972	          method: 'POST',
973	          headers: { 'Content-Type': 'application/json' },
974	          body: JSON.stringify(payload)
975	        });
976	        const result = await resp.json();
977	
978	        if (resp.ok && result.status === 'ok') {
979	          setStatus(`🎉 地图路网热重载成功! 生成 ${result.stations_count} 站点, ${result.road_nodes_count} 通行路口, ${result.edges_count} 拓扑边`, true);
980	          alert(`✅ 地图拓扑生成成功并生效！\n站点: ${result.stations_count} 个\n通行路口: ${result.road_nodes_count} 个\n拓扑折线边: ${result.edges_count} 条\n版本Hash: ${result.map_hash}`);
981	          fetchSnapshot();
982	        } else {
983	          setStatus(`❌ 地图导入失败: ${result.message || result.error}`, false);
984	          alert(`❌ 地图导入失败: ${result.message || result.error}`);
985	        }
986	      } catch (err) {
987	        setStatus(`网络错误: ${err.message}`, false);
988	        alert(`请求失败: ${err.message}`);
989	      } finally {
990	        uploadMapBtn.disabled = false;
991	        uploadMapBtn.textContent = "🚀 一键生成路网并热重载";
992	      }
993	    });
