454	  rclcpp::Service<amr_dispatcher_interfaces::srv::RestoreVda5050Link>::SharedPtr
455	      restore_vda5050_link_srv_;
456	  // ExecuteMission action server（HandleGoal 校验 + HandleAccepted 入队，不起线程）
457	  rclcpp_action::Server<ExecuteMission>::SharedPtr execute_action_server_;
458	  // NavigateSequence 客户端（navigation_backend=action 时向桥接节点发单点 goal）
459	  rclcpp_action::Client<NavigateSequence>::SharedPtr nav_client_;
460	  // mission_id -> 仍在执行的 ExecuteMission goal handle（终态时查表 finish 并移除）
461	  std::unordered_map<std::string, std::shared_ptr<GoalHandleExecute>> execute_goal_handles_;
462	  // mission_id -> 派发起点（PublishState 里按直线距离折算 percent_complete）
463	  std::unordered_map<std::string, amr_dispatcher_core::path_tracking::Pose2D> mission_dispatch_start_;
464	  // mission_id -> 派发时刻（ExecuteMission result.total_duration_sec 计算用，
465	  // 终态时在 FinishExecuteGoal/CompleteMission/FailMission/取消收口里遗忘）
466	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_dispatch_time_;
467	  // 导航后端：plan（默认，原 /plan 路径不变）| action（发 /navigate_sequence 单点 goal）
468	  std::string navigation_backend_{"plan"};
469	  // action 模式在途导航 goal 的归属任务与句柄（取消/终态时级联 async_cancel_goal）
470	  std::string pending_nav_mission_id_;
471	  GoalHandleNavigate::SharedPtr pending_nav_goal_handle_;
472	
473	  // Peek→Reserve→Pop：排队任务预留路由锁失败 -> 该任务仍在等的锁列表
474	  //（喂 DeadlockSnapshot.allocation_graph.waiting_for，终态/取消时遗忘）
475	  std::unordered_map<std::string, std::vector<std::string>> pending_wait_;
476	  // mission_id -> 路由锁预留成功时刻（喂 DeadlockSnapshot.reservation_acquired_at，
477	  // 长持锁启发式取证；仅任务派发预留记账，人工 ReserveResourceCb 不记，避免误报）
478	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_reserved_at_;
479	
480	  // ---- Task 5：逐段路权动态释放与断链安全守卫（Spec §5.2/§5.3）----
481	  // 单台受管 VDA 5050 小车的链路态（单线程 spin，无并发；M7 约束适用）
482	  // ROS 订阅句柄：只放 rclcpp 对象，生命周期随 on_cleanup/SetupVda5050Links 收口
483	  struct Vda5050LinkSubs {
484	    rclcpp::Subscription<std_msgs::msg::String>::SharedPtr state_sub;
485	    rclcpp::Subscription<std_msgs::msg::Bool>::SharedPtr online_sub;
486	  };
487	  // 两个表的 key 集合必须一致（都由 vda5050_vehicle_ids_ 驱动），
488	  // 拆开是为了让"链路纯数据"能直接喂给 core 的纯函数（守卫/选车）。
489	  std::unordered_map<std::string, Vda5050LinkSubs> vda5050_link_subs_;
490	  std::unordered_map<std::string, amr_dispatcher_core::fleet::Vda5050LinkState>
491	      vda5050_link_states_;
492	  // vehicle_id -> 隔离态集合（人工强清后置入；恢复时移除）。
493	  // 隔离车仍可见/可审计，但不参与自动分配（选车时视为不合格）。
494	  std::unordered_set<std::string> vda5050_quarantined_;
495	  // mission_id -> 派发时刻的行驶路径（travel order；Peek 阶段只留锁列表，路径在此存档，
496	  // 供 state 回推身后锁；终态经 ForgetMissionDispatchState 遗忘）
497	  std::unordered_map<std::string, std::vector<std::string>> mission_route_paths_;
498	  // mission_id -> 承接该单的受管车辆（PublishVda5050Order 下发时登记）。
499	  // 人工强清离线链路时按此反查"该车名下"的 mission —— 不能靠"路径存档存在"推断，
500	  // 那会把其他车辆的 mission 锁一并误判为该车名下（多车场景误释放）。
501	  std::unordered_map<std::string, std::string> vda5050_mission_vehicle_;
502	  // state 陈旧阈值（秒）：在线但超时未上报 -> 软看门狗告警（不释放、不阻塞）
503	  double vda5050_state_stale_sec_{5.0};
504	
505	  // ---- Task 6：VDA 5050 订单发布端（补 Task 5 评审 I2 的发布链路缺口）----
506	  // 保序受管车辆清单（SetupVda5050Links 与 vda5050_links_ 同步填充；
507	  // round-robin 绑定需要确定性顺序，unordered_map 遍历序不可依赖）
508	  std::vector<std::string> vda5050_vehicle_ids_;
509	  // vehicle_id -> send_order 发布端（on_configure 按清单一次建齐，on_activate 激活；
510	  // 网关侧订阅是懒建的，ROS 2 发布端不依赖对端存在）
511	  std::unordered_map<std::string, rclcpp_lifecycle::LifecyclePublisher<std_msgs::msg::String>::SharedPtr>
512	      vda5050_order_pubs_;
513	  // vehicle_id -> 下一单 order_update_id（同车每派一次递增，VDA 5050 更新语义）
514	  std::unordered_map<std::string, std::uint32_t> vda5050_next_order_update_id_;
515	  // round-robin 游标（按车推进；键缺失时回绕到 0）
516	  std::size_t vda5050_rr_cursor_ = 0;
517	
518	  // 12 Core Services SharedPtrs
519	  rclcpp::Service<amr_dispatcher_interfaces::srv::EnqueueMission>::SharedPtr enqueue_srv_;
520	  rclcpp::Service<amr_dispatcher_interfaces::srv::CancelQueuedMission>::SharedPtr cancel_queued_srv_;
521	  rclcpp::Service<amr_dispatcher_interfaces::srv::PreemptMission>::SharedPtr preempt_srv_;
522	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>::SharedPtr reprioritize_srv_;
523	  rclcpp::Service<amr_dispatcher_interfaces::srv::EstimateMissionCost>::SharedPtr estimate_cost_srv_;
524	  rclcpp::Service<amr_dispatcher_interfaces::srv::BlockStationRoute>::SharedPtr block_route_srv_;
525	  rclcpp::Service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>::SharedPtr detect_deadlock_srv_;
526	  rclcpp::Service<amr_dispatcher_interfaces::srv::ListStations>::SharedPtr list_stations_srv_;
527	  rclcpp::Service<amr_dispatcher_interfaces::srv::ListTrafficReservations>::SharedPtr list_reservations_srv_;
528	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>::SharedPtr reserve_facility_srv_;
529	  rclcpp::Service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>::SharedPtr snapshot_srv_;
530	  rclcpp::Service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>::SharedPtr validate_site_srv_;
531	
532	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::DispatcherState>::SharedPtr state_pub_;
533	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::MissionEvent>::SharedPtr event_pub_;
534	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::TopologyState>::SharedPtr topology_pub_;
535	  rclcpp_lifecycle::LifecyclePublisher<nav_msgs::msg::Path>::SharedPtr plan_pub_;
536	
537	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::TrackingError>::SharedPtr tracking_error_sub_;
538	  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odom_sub_;
539	
540	  // ---- P0.6 / A4：per-vehicle 话题隔离 ----
541	  // vehicle_ids 清单（保序去重，来自参数 vehicle_ids；空 = 单车兼容模式）。
542	  std::vector<std::string> vehicle_ids_;
543	  // vehicle_id -> /plan/{vid} 发布端（on_configure 建，on_activate 激活，on_cleanup 释放）
544	  std::unordered_map<std::string, rclcpp_lifecycle::LifecyclePublisher<nav_msgs::msg::Path>::SharedPtr>
545	      vehicle_plan_pubs_;
546	  // vehicle_id -> /odom/{vid} 订阅
547	  std::unordered_map<std::string, rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr>
548	      vehicle_odom_subs_;
549	  // vehicle_id -> /tracking/error/{vid} 订阅
550	  std::unordered_map<std::string, rclcpp::Subscription<amr_dispatcher_interfaces::msg::TrackingError>::SharedPtr>
551	      vehicle_tracking_error_subs_;
552	  // vehicle_id -> 最新里程计位姿（Pose2D + has_odom 标志）。
553	  // 与 legacy 的 current_pose_/has_odom_ 并存：全局 /odom 仍只喂 legacy 字段。
554	  struct VehiclePose {
555	    amr_dispatcher_core::path_tracking::Pose2D pose{};
556	    bool has_odom = false;
557	  };
558	  std::unordered_map<std::string, VehiclePose> vehicle_poses_;
559	
560	  // ---- Phase 7: 在途任务等待表与交通协调管理 ----
561	  // mission_id -> 在途等待前方资源锁集合 (例如在道口等待 route_edge:B__C)
562	  std::unordered_map<std::string, std::vector<std::string>> in_flight_pending_wait_;
563	  // vehicle_id -> 最近一次确认到达的安全停靠节点 ID
564	  std::unordered_map<std::string, std::string> vehicle_safe_nodes_;
565	
566	  // ---- Phase 8: 工业物理设施适配器集成与预约管理 ----
567	  std::unique_ptr<amr_dispatcher_core::facility::FacilityCatalogReloader> facility_reloader_;
568	  amr_dispatcher_core::facility::FacilityReservationMap facility_reservations_;
569	  amr_dispatcher_core::facility::MissionResourceMap mission_facility_resources_;
570	  std::unordered_map<std::string, std::shared_ptr<amr_dispatcher_core::facility::IFacilityAdapter>> facility_adapters_;
571	
572	  rclcpp::TimerBase::SharedPtr schedule_timer_;
573	  rclcpp::TimerBase::SharedPtr deadlock_timer_;
574	  rclcpp::TimerBase::SharedPtr state_timer_;
575	  rclcpp::TimerBase::SharedPtr reload_timer_;  // 1Hz 驱动站点目录 mtime 热重载
576	  rclcpp::node_interfaces::OnSetParametersCallbackHandle::SharedPtr param_callback_handle_;
577	};
578	
579	}  // namespace amr_dispatcher_ros
