253	  // B3：交通协调模式（static = 现网行为；time_space = 时空窗预约；cbs = 高层冲突树协同）
254	  traffic_mode_ = get_parameter("traffic_mode").as_string();
255	  if (traffic_mode_ != "static" && traffic_mode_ != "time_space" && traffic_mode_ != "cbs") {
256	    RCLCPP_ERROR(get_logger(),
257	                 "Invalid traffic_mode '%s' — falling back to 'static' (unknown mode is not "
258	                 "guessed)",
259	                 traffic_mode_.c_str());
260	    traffic_mode_ = "static";
261	  }
262	  time_space_timing_.cruise_speed_mps = get_parameter("time_space_cruise_speed_mps").as_double();
263	  time_space_timing_.accel_overhead_sec =
264	      get_parameter("time_space_accel_overhead_sec").as_double();
265	  time_space_timing_.turn_overhead_sec =
266	      get_parameter("time_space_turn_overhead_sec").as_double();
267	  time_space_timing_.safety_margin_m = get_parameter("time_space_safety_margin_m").as_double();
268	  time_space_timing_.min_headway_sec = get_parameter("time_space_min_headway_sec").as_double();
269	  RCLCPP_INFO(get_logger(), "Traffic coordination mode: %s", traffic_mode_.c_str());
270	
271	  // P0.6 / A6：选车上下文（静态目录 + 参数）
272	  required_capability_ = get_parameter("required_capability").as_string();
273	  min_battery_percent_ = get_parameter("min_battery_percent").as_double();
274	  {
275	    const std::string label = get_parameter("vehicle_selection_strategy").as_string();
276	    if (!amr_dispatcher_core::fleet::ParseVehicleSelectionStrategy(
277	            label, &vehicle_selection_strategy_)) {
278	      RCLCPP_WARN(get_logger(),
279	                  "Invalid vehicle_selection_strategy '%s' — falling back to 'nearest' "
280	                  "(unknown strategies are never guessed)",
281	                  label.c_str());
282	      vehicle_selection_strategy_ = amr_dispatcher_core::fleet::VehicleSelectionStrategy::kNearest;
283	    }
284	    RCLCPP_INFO(get_logger(), "Vehicle selection strategy: %s",
285	                amr_dispatcher_core::fleet::VehicleSelectionStrategyLabel(
286	                    vehicle_selection_strategy_));
287	  }
288	  vehicle_state_max_age_ms_ = get_parameter("vehicle_state_max_age_ms").as_int();
289	  LoadFleetCatalog();
290	
291	  // Phase 8: 物理设施目录加载与适配器初始化
292	  const std::string facility_file = get_parameter("facility_catalog_file").as_string();
293	  if (!facility_file.empty()) {
294	    facility_reloader_ =
295	        std::make_unique<amr_dispatcher_core::facility::FacilityCatalogReloader>(facility_file);
296	    if (facility_reloader_->loaded()) {
297	      RCLCPP_INFO(get_logger(), "Loaded %zu facility resources from %s",
298	                  facility_reloader_->catalog().resources.size(), facility_file.c_str());
299	      // 根据配置生成适配器
300	      for (const auto& res : facility_reloader_->catalog().resources) {
301	        if (res.protocol == "modbus_tcp") {
302	          amr_dispatcher_core::facility::ModbusFacilityConfig cfg;
303	          cfg.facility_id = res.id;
304	          cfg.type = (res.type == "door")
305	                         ? amr_dispatcher_core::facility::FacilityType::kDoor
306	                         : amr_dispatcher_core::facility::FacilityType::kElevator;
307	          cfg.ip = res.ip;
308	          cfg.port = res.port;
309	          cfg.unit_id = res.unit_id;
