311	              std::make_shared<amr_dispatcher_core::facility::ModbusFacilityAdapter>(cfg);
312	        } else {
313	          facility_adapters_[res.id] =
314	              std::make_shared<amr_dispatcher_core::facility::MockFacilityAdapter>(
315	                  res.id, (res.type == "door")
316	                              ? amr_dispatcher_core::facility::FacilityType::kDoor
317	                              : amr_dispatcher_core::facility::FacilityType::kElevator);
318	        }
319	      }
320	    }
321	  }
322	
323	  // 批次 6.2：低电量自动插充电单上下文。
324	  // 默认 auto_charging_enabled=false 且 station 为空 -> PlanAutoChargingTick 首行即
325	  // 直接返回，legacy 单车与未配置部署的行为与改动前逐字一致。
326	  auto_charging_enabled_ = get_parameter("auto_charging_enabled").as_bool();
327	  auto_charging_station_ = get_parameter("auto_charging_station").as_string();
328	  auto_charging_opportunity_threshold_percent_ =
329	      get_parameter("auto_charging_opportunity_threshold_percent").as_double();
330	  auto_charging_critical_threshold_percent_ =
331	      get_parameter("auto_charging_critical_threshold_percent").as_double();
332	  auto_charging_opportunity_priority_ =
333	      static_cast<int>(get_parameter("auto_charging_opportunity_priority").as_int());
334	  auto_charging_critical_priority_ =
335	      static_cast<int>(get_parameter("auto_charging_critical_priority").as_int());
336	  if (auto_charging_enabled_) {
337	    if (auto_charging_station_.empty()) {
338	      // 开了开关却没给充电站 = 配置错误。明确报错并关闭，避免"以为开了其实从不触发"。
339	      RCLCPP_ERROR(get_logger(),
340	                   "auto_charging_enabled=true but auto_charging_station is empty — "
341	                   "auto charging stays DISABLED (never guess a charger station)");
342	      auto_charging_enabled_ = false;
343	    } else if (auto_charging_critical_threshold_percent_ >
344	               auto_charging_opportunity_threshold_percent_) {
345	      RCLCPP_ERROR(get_logger(),
