state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
    "/dispatcher/state", 10);
event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
    "/dispatcher/events", 20);
plan_pub_ = create_publisher<nav_msgs::msg::Path>("/plan", 1);
// 拓扑状态：safety_gate（deadlock_active_）与 visualizer（绿锁边/红警戒柱）的死锁输入
topology_pub_ = create_publisher<amr_dispatcher_interfaces::msg::TopologyState>(
    "/dispatcher/topology_state", 10);

// 位姿与到达信号订阅：path_tracker 的 TrackingError.arrived 驱动任务完成
odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
    "/odom", 10, std::bind(&DispatcherNode::OdomCb, this, std::placeholders::_1));
tracking_error_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
    "/tracking/error", 10,
    std::bind(&DispatcherNode::TrackingErrorCb, this, std::placeholders::_1));

// Task 5：VDA 5050 状态/链路接入（逐段解锁 + 断链守卫），按参数建订阅
SetupVda5050Links(get_parameter("vda5050_vehicles").as_string());
// 批次 2：把快照里的隔离车辆重新置为隔离（SetupVda5050Links 已先清空链路态表）
for (const auto& vid : restored_quarantined_) {
  if (SetVehicleQuarantined(vid, true)) {
    RCLCPP_WARN(get_logger(), "Restored vehicle %s as QUARANTINED (from state snapshot)",
                vid.c_str());
  } else {
    RCLCPP_WARN(get_logger(),
                "Snapshot lists %s as quarantined but it is not a managed vehicle; ignored",
                vid.c_str());
  }
}
restored_quarantined_.clear();

// P0.6 / A4：per-vehicle 计划发布端与位姿/到达订阅（空清单 = 单车兼容，零行为变化）
SetupVehicleTopics(get_parameter("vehicle_ids").as_string());

// B3：交通协调模式（static = 现网行为；time_space = 时空窗预约；cbs = 高层冲突树协同）
traffic_mode_ = get_parameter("traffic_mode").as_string();
if (traffic_mode_ != "static" && traffic_mode_ != "time_space" && traffic_mode_ != "cbs") {
  RCLCPP_ERROR(get_logger(),
               "Invalid traffic_mode '%s' — falling back to 'static' (unknown mode is not "
               "guessed)",
               traffic_mode_.c_str());
  traffic_mode_ = "static";
}
time_space_timing_.cruise_speed_mps = get_parameter("time_space_cruise_speed_mps").as_double();
time_space_timing_.accel_overhead_sec =
    get_parameter("time_space_accel_overhead_sec").as_double();
time_space_timing_.turn_overhead_sec =
    get_parameter("time_space_turn_overhead_sec").as_double();
time_space_timing_.safety_margin_m = get_parameter("time_space_safety_margin_m").as_double();
time_space_timing_.min_headway_sec = get_parameter("time_space_min_headway_sec").as_double();
RCLCPP_INFO(get_logger(), "Traffic coordination mode: %s", traffic_mode_.c_str());

// P0.6 / A6：选车上下文（静态目录 + 参数）
required_capability_ = get_parameter("required_capability").as_string();
min_battery_percent_ = get_parameter("min_battery_percent").as_double();
{
  const std::string label = get_parameter("vehicle_selection_strategy").as_string();
  if (!amr_dispatcher_core::fleet::ParseVehicleSelectionStrategy(
          label, &vehicle_selection_strategy_)) {
    RCLCPP_WARN(get_logger(),
                "Invalid vehicle_selection_strategy '%s' — falling back to 'nearest' "
                "(unknown strategies are never guessed)",
                label.c_str());
    vehicle_selection_strategy_ = amr_dispatcher_core::fleet::VehicleSelectionStrategy::kNearest;
  }
  RCLCPP_INFO(get_logger(), "Vehicle selection strategy: %s",
              amr_dispatcher_core::fleet::VehicleSelectionStrategyLabel(
                  vehicle_selection_strategy_));
}
vehicle_state_max_age_ms_ = get_parameter("vehicle_state_max_age_ms").as_int();
LoadFleetCatalog();

// Phase 8: 物理设施目录加载与适配器初始化
const std::string facility_file = get_parameter("facility_catalog_file").as_string();
if (!facility_file.empty()) {
  facility_reloader_ =
      std::make_unique<amr_dispatcher_core::facility::FacilityCatalogReloader>(facility_file);
  if (facility_reloader_->loaded()) {
    RCLCPP_INFO(get_logger(), "Loaded %zu facility resources from %s",
                facility_reloader_->catalog().resources.size(), facility_file.c_str());
    // 根据配置生成适配器
    for (const auto& res : facility_reloader_->catalog().resources) {
      if (res.protocol == "modbus_tcp") {
        amr_dispatcher_core::facility::ModbusFacilityConfig cfg;
        cfg.facility_id = res.id;
        cfg.type = (res.type == "door")
                       ? amr_dispatcher_core::facility::FacilityType::kDoor
                       : amr_dispatcher_core::facility::FacilityType::kElevator;
        cfg.ip = res.ip;
        cfg.port = res.port;
        cfg.unit_id = res.unit_id;
        facility_adapters_[res.id] =
            std::make_shared<amr_dispatcher_core::facility::ModbusFacilityAdapter>(cfg);
      } else {
        facility_adapters_[res.id] =
            std::make_shared<amr_dispatcher_core::facility::MockFacilityAdapter>(
                res.id, (res.type == "door")
                            ? amr_dispatcher_core::facility::FacilityType::kDoor
                            : amr_dispatcher_core::facility::FacilityType::kElevator);
      }
    }
  }
}

// 批次 6.2：低电量自动插充电单上下文。
// 默认 auto_charging_enabled=false 且 station 为空 -> PlanAutoChargingTick 首行即
// 直接返回，legacy 单车与未配置部署的行为与改动前逐字一致。
auto_charging_enabled_ = get_parameter("auto_charging_enabled").as_bool();
auto_charging_station_ = get_parameter("auto_charging_station").as_string();
auto_charging_opportunity_threshold_percent_ =
    get_parameter("auto_charging_opportunity_threshold_percent").as_double();
auto_charging_critical_threshold_percent_ =
    get_parameter("auto_charging_critical_threshold_percent").as_double();
auto_charging_opportunity_priority_ =
    static_cast<int>(get_parameter("auto_charging_opportunity_priority").as_int());
auto_charging_critical_priority_ =
    static_cast<int>(get_parameter("auto_charging_critical_priority").as_int());
if (auto_charging_enabled_) {
  if (auto_charging_station_.empty()) {
    // 开了开关却没给充电站 = 配置错误。明确报错并关闭，避免"以为开了其实从不触发"。
    RCLCPP_ERROR(get_logger(),
                 "auto_charging_enabled=true but auto_charging_station is empty — "
                 "auto charging stays DISABLED (never guess a charger station)");
    auto_charging_enabled_ = false;
  } else if (auto_charging_critical_threshold_percent_ >
             auto_charging_opportunity_threshold_percent_) {
    RCLCPP_ERROR(get_logger(),
                 "auto charging critical threshold (%.1f) exceeds opportunity threshold "
                 "(%.1f) — auto charging stays DISABLED",
                 auto_charging_critical_threshold_percent_,
                 auto_charging_opportunity_threshold_percent_);
    auto_charging_enabled_ = false;
  } else {
    RCLCPP_INFO(get_logger(),
                "Auto charging enabled: station=%s, opportunity<=%.1f%% (priority %d), "
                "critical<=%.1f%% (priority %d)",
                auto_charging_station_.c_str(), auto_charging_opportunity_threshold_percent_,
                auto_charging_opportunity_priority_,
                auto_charging_critical_threshold_percent_,
                auto_charging_critical_priority_);

