1	// HTTP 请求解析的安全边界（纯函数，无 IO、无异常、无时钟）。
2	//
3	// 背景：旧网关用 std::stoi 直接解析 Content-Length 与 prio，任何一个畸形值
4	// 都会抛 std::invalid_argument 并且没有被捕获 —— 整个网关进程 terminate。
5	// 另外路由用 path.find(...) 做子串匹配，`/api/v1/ordersXYZ` 也会命中订单路由。
6	// 这里把"解析"与"路由匹配"抽成可单测的纯函数，网关只负责 IO 与副作用。
7	#pragma once
8	
9	#include <cctype>
10	#include <cstddef>
11	#include <cstdint>
12	#include <string>
13	
14	namespace amr_dispatcher_tools {
15	
16	// 请求体上限（1 MiB）：地图上传是本网关最大的合法请求，远小于此值。
17	inline constexpr std::size_t kMaxRequestBytes = 1024U * 1024U;
18	// 请求头段上限（8 KiB）：正常请求头只有几百字节。
19	inline constexpr std::size_t kMaxHeaderBytes = 8U * 1024U;
20	// 单连接收发超时（秒）：静默连接不能永久占住工作线程。
21	inline constexpr int kSocketTimeoutSec = 5;
22	
23	// Content-Length 的解析结果：
24	//   kMissing  —— 没有该头部（GET 等无体请求，合法）
25	//   kOk       —— 合法且在上限内
26	//   kInvalid  —— 非数字 / 负数 / 溢出（调用方应回 400）
27	//   kTooLarge —— 合法但超过 kMaxRequestBytes（调用方应回 413）
28	enum class ContentLengthStatus { kMissing, kOk, kInvalid, kTooLarge };
29	
30	// 去掉首尾空白（空格、制表符、CR、LF）。
31	inline std::string TrimWhitespace(const std::string& s) {
32	  std::size_t begin = 0;
33	  while (begin < s.size() &&
34	         (s[begin] == ' ' || s[begin] == '\t' || s[begin] == '\r' || s[begin] == '\n')) {
35	    ++begin;
36	  }
37	  std::size_t end = s.size();
38	  while (end > begin &&
39	         (s[end - 1] == ' ' || s[end - 1] == '\t' || s[end - 1] == '\r' || s[end - 1] == '\n')) {
40	    --end;
41	  }
42	  return s.substr(begin, end - begin);
43	}
44	
45	// 解析 Content-Length 的值（不含头部名）。只接受纯十进制数字。
46	inline ContentLengthStatus ParseContentLength(const std::string& value, std::size_t* out) {
47	  if (out != nullptr) {
48	    *out = 0;
49	  }
50	  const std::string trimmed = TrimWhitespace(value);
51	  if (trimmed.empty()) {
52	    return ContentLengthStatus::kMissing;
53	  }
54	  for (const char c : trimmed) {
55	    if (c < '0' || c > '9') {
56	      return ContentLengthStatus::kInvalid;  // 负数（'-'）、小数、字母一律非法
57	    }
58	  }
59	  // 用 unsigned long long 累计并逐位判溢出：超大数值必须是明确的 kInvalid，
60	  // 绝不能被截断成一个"看起来合法"的小长度。
61	  unsigned long long acc = 0;
62	  for (const char c : trimmed) {
63	    const unsigned long long digit = static_cast<unsigned long long>(c - '0');
64	    if (acc > (18446744073709551615ULL - digit) / 10ULL) {
65	      return ContentLengthStatus::kInvalid;  // 数值溢出
66	    }
67	    acc = acc * 10ULL + digit;
68	  }
69	  if (acc > static_cast<unsigned long long>(kMaxRequestBytes)) {
70	    if (out != nullptr) {
71	      *out = 0;  // 不返回被截断的巨值，调用方只按状态码处置
72	    }
73	    return ContentLengthStatus::kTooLarge;
74	  }
75	  if (out != nullptr) {
76	    *out = static_cast<std::size_t>(acc);
77	  }
78	  return ContentLengthStatus::kOk;
79	}
80	
81	// 取请求 URI 的路径部分：剥离 query（`?` 之后）与 fragment（`#` 之后）。
82	// 兼容代理常见 absolute-form：`http://host:port/path?q` -> `/path`。
83	inline std::string RequestPathOnly(const std::string& target) {
84	  std::string path = target;
85	  const std::size_t scheme = path.find("://");
86	  if (scheme != std::string::npos) {
87	    const std::size_t path_begin = path.find('/', scheme + 3);
88	    path = (path_begin == std::string::npos) ? "/" : path.substr(path_begin);
89	  }
90	  const std::size_t query = path.find('?');
91	  if (query != std::string::npos) {
92	    path = path.substr(0, query);
93	  }
94	  const std::size_t fragment = path.find('#');
95	  if (fragment != std::string::npos) {
96	    path = path.substr(0, fragment);
97	  }
98	  return path;
99	}
100	
101	// 取请求 URI 的 query 部分（不含 `?`；无 query 返回空串）。
102	inline std::string RequestQueryOnly(const std::string& target) {
103	  const std::size_t query = target.find('?');
104	  if (query == std::string::npos) {
105	    return "";
106	  }
107	  std::string rest = target.substr(query + 1);
108	  const std::size_t fragment = rest.find('#');
109	  if (fragment != std::string::npos) {
110	    rest = rest.substr(0, fragment);
111	  }
112	  return rest;
113	}
114	
115	// 精确路径匹配：不再用子串包含，杜绝 `/api/v1/ordersXYZ` 命中订单路由。
116	inline bool PathMatches(const std::string& path, const std::string& expected) {
117	  return path == expected;
118	}
119	
120	inline bool PathMatchesAny(const std::string& path, const std::string& a, const std::string& b) {
121	  return PathMatches(path, a) || PathMatches(path, b);
122	}
123	
124	// 在头部块里大小写不敏感地查一个字段，返回去掉首尾空白后的值。
125	// head_block 是请求行之后、空行之前的全部内容（可含请求行，按行扫描即可）。
126	inline bool FindHeaderValue(const std::string& head_block, const std::string& name,
127	                            std::string* out) {
128	  if (out != nullptr) {
129	    out->clear();
130	  }
131	  std::size_t line_begin = 0;
132	  while (line_begin < head_block.size()) {
133	    std::size_t line_end = head_block.find("\r\n", line_begin);
134	    if (line_end == std::string::npos) {
135	      line_end = head_block.size();
136	    }
137	    const std::string line = head_block.substr(line_begin, line_end - line_begin);
138	    const std::size_t colon = line.find(':');
139	    if (colon != std::string::npos) {
140	      std::string field = TrimWhitespace(line.substr(0, colon));
141	      if (field.size() == name.size()) {
142	        bool same = true;
143	        for (std::size_t i = 0; i < field.size(); ++i) {
144	          const char a = static_cast<char>(std::tolower(static_cast<unsigned char>(field[i])));
145	          const char b = static_cast<char>(std::tolower(static_cast<unsigned char>(name[i])));
146	          if (a != b) {
147	            same = false;
148	            break;
149	          }
150	        }
151	        if (same) {
152	          if (out != nullptr) {
153	            *out = TrimWhitespace(line.substr(colon + 1));
154	          }
155	          return true;
156	        }
157	      }
158	    }
159	    line_begin = line_end + 2;  // 跳过 "\r\n"
160	  }
161	  return false;
162	}
163	
164	// 严格整数解析（用于 prio 这类查询参数）。
165	// 旧实现 `std::stoi` 遇到 "abc" 直接抛异常并打死网关；且 "5x" 会被静默截成 5。
166	enum class IntParseStatus { kOk, kInvalid, kOutOfRange };
167	
168	inline IntParseStatus ParseInt32Strict(const std::string& text, std::int32_t* out) {
169	  if (out != nullptr) {
170	    *out = 0;
171	  }
172	  const std::string trimmed = TrimWhitespace(text);
173	  if (trimmed.empty()) {
174	    return IntParseStatus::kInvalid;
175	  }
176	  std::size_t i = 0;
177	  bool negative = false;
178	  if (trimmed[0] == '+' || trimmed[0] == '-') {
179	    negative = (trimmed[0] == '-');
180	    ++i;
181	    if (i >= trimmed.size()) {
182	      return IntParseStatus::kInvalid;
183	    }
184	  }
185	  long long acc = 0;
186	  for (; i < trimmed.size(); ++i) {
187	    const char c = trimmed[i];
188	    if (c < '0' || c > '9') {
189	      return IntParseStatus::kInvalid;
190	    }
191	    acc = acc * 10 + (c - '0');
192	    if (acc > 2147483648LL) {
193	      return IntParseStatus::kOutOfRange;
194	    }
195	  }
196	  if (negative) {
197	    acc = -acc;
198	  }
199	  if (acc < -2147483648LL || acc > 2147483647LL) {
200	    return IntParseStatus::kOutOfRange;
201	  }
202	  if (out != nullptr) {
203	    *out = static_cast<std::int32_t>(acc);
204	  }
205	  return IntParseStatus::kOk;
206	}
207	
208	// 判断请求是否声明了分块传输（本网关不支持，调用方应回 400 而不是猜长度）。
209	inline bool HasChunkedTransferEncoding(const std::string& head_block) {
210	  std::string value;
211	  if (!FindHeaderValue(head_block, "Transfer-Encoding", &value)) {
212	    return false;
213	  }
214	  for (char& c : value) {
215	    c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
216	  }
217	  return value.find("chunked") != std::string::npos;
218	}
